# Test of Reasoning / Mental Ability (Part A): problem solving, analysis, judgment and decision
# making (blood relations, directions, ranking, syllogisms, arrangements, assumptions and courses
# of action, police judgment), spatial orientation written as text (dice, cubes, turns, mirrors).
# Non-verbal figure items and visual memory need pictures and are not modelled.
ITEMS = [
    # ---------- Practice Test 1 ----------
    S(1, 2, "Blood relations", "Pointing to a woman, Ramesh says, \"Her mother's only son is my father.\" How is the woman related to Ramesh?",
      ["Aunt", "Sister", "Mother", "Grandmother"],
      "The woman's mother's only son is the woman's brother, and he is Ramesh's father. So the woman is his father's sister, Ramesh's aunt."),
    S(1, 1, "Directions", "Ravi walks 8 km east, turns left and walks 6 km, then turns left again and walks 8 km. Where is he now from his starting point?",
      ["6 km north", "6 km south", "10 km north", "14 km east"],
      "Left from east is north, and left again is west. The 8 km east and 8 km west cancel, leaving him 6 km north of the start."),
    S(1, 1, "Ranking", "In a class, Kiran is 12th from the top and 25th from the bottom. How many students are in the class?",
      ["36", "37", "35", "38"],
      "Total = 12 + 25 - 1 = 36. Kiran is counted in both positions, so one is taken away."),
    S(1, 2, "Syllogism", "Statements: All constables are trained. Some trained people are drivers. Conclusions: I. Some constables are drivers. II. Some drivers are trained. Which conclusion follows?",
      ["Only II follows", "Only I follows", "Both I and II follow", "Neither I nor II follows"],
      "The trained people who are drivers need not be constables, so I does not follow. \"Some trained people are drivers\" can be reversed to \"some drivers are trained\", so II follows."),
    S(1, 2, "Arrangement", "Seven files P, Q, R, S, T, U and V are stacked one above another. P is at the top and V at the bottom. S is directly below P. U is directly below S and directly above Q. Q is directly above R, and T is directly above V. Which file is fourth from the top?",
      ["Q", "U", "R", "T"],
      "From the top: P, S, U, Q, R, T, V. The fourth file is Q."),
    S(1, 2, "Assumptions", "Statement: \"Helmets are now compulsory for pillion riders on two-wheelers too.\" Assumptions: I. Pillion riders can also suffer head injuries in accidents. II. Most riders already wear helmets. Which assumption is implicit?",
      ["Only I is implicit", "Only II is implicit", "Both are implicit", "Neither is implicit"],
      "The rule only makes sense if pillion riders are at risk of head injury, so I is assumed. The rule says nothing about how many riders already wear helmets, so II is not."),
    S(1, 2, "Judgment", "A constable on night patrol sees smoke coming out of a locked shop. What should he do first?",
      ["Alert the fire service and control room", "Wait for the owner to come and open it", "Break in alone and search the shop", "Note it in the diary next morning"],
      "Lives and property are at risk, so the first step is to call the fire service and inform the control room. Waiting or only recording it lets the fire spread, and entering alone is unsafe."),
    S(1, 3, "Coded relations", "P × Q means P is the brother of Q, P ÷ Q means P is the mother of Q, and P + Q means P is the father of Q. What does A ÷ B × C mean?",
      ["A is the mother of C", "A is the sister of C", "A is the aunt of C", "A is the daughter of C"],
      "A ÷ B: A is the mother of B. B × C: B is the brother of C. So C is A's child as well, and A is the mother of C."),
    S(1, 1, "Dice", "On a die, 1 is opposite 6, 2 is opposite 5 and 3 is opposite 4. If 2 is on top and 3 faces you, which number is at the bottom?",
      ["5", "4", "6", "1"],
      "The bottom face is opposite the top face. 2 is on top and 5 is opposite 2, so 5 is at the bottom. Which face points at you does not change this."),
    S(1, 2, "Mirror images", "A clock seen in a mirror shows 4:20. What is the actual time?",
      ["7:40", "8:40", "7:20", "8:20"],
      "For a mirror image, subtract the time shown from 11:60: 11:60 - 4:20 = 7:40."),
    S(1, 2, "Directions", "One evening before sunset, Anil walks towards a lamp post and his own shadow falls straight behind him. Which direction is he walking?",
      ["West", "East", "North", "South"],
      "In the evening the sun is in the west, so shadows point east. If his shadow is behind him, the sun is in front, and he is walking west."),
    S(1, 2, "Inequality", "Statements: M < N ≤ O, O > P, P ≥ Q. Conclusions: I. M < O II. N > Q. Which conclusion follows?",
      ["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"],
      "M < N ≤ O gives M < O, so I follows. N and Q are linked only through O > P ≥ Q, which does not fix how N compares with Q, so II does not follow."),

    # ---------- Practice Test 2 ----------
    S(2, 2, "Blood relations", "Pointing to a boy, Meena says, \"He is the son of the only daughter of my father.\" How is the boy related to Meena?",
      ["Son", "Brother", "Nephew", "Cousin"],
      "The only daughter of Meena's father is Meena herself. So the boy is her son."),
    S(2, 1, "Directions", "From her house, Lakshmi goes 10 km south, then 10 km west, then 20 km north. In which direction is she now from her house?",
      ["North-west", "North-east", "South-west", "West"],
      "Overall she is 20 - 10 = 10 km north and 10 km west of her house, so she is to the north-west."),
    S(2, 2, "Ranking", "In a queue of 30 people, Hari is 11th from the front and Mohan is 5 places behind Hari. What is Mohan's position from the back?",
      ["15th", "14th", "16th", "19th"],
      "Mohan is 11 + 5 = 16th from the front, so from the back he is 30 - 16 + 1 = 15th."),
    S(2, 2, "Syllogism", "Statements: No cook is a cleaner. All cleaners are workers. Conclusions: I. Some workers are not cooks. II. No worker is a cook. Which conclusion follows?",
      ["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"],
      "The cleaners are workers and none of them is a cook, so some workers are not cooks (I). Other workers may still be cooks, so II does not follow."),
    S(2, 2, "Arrangement", "Five houses in a row are painted red, blue, green, white and yellow. The red house is at the left end. The blue house is in the middle. The green house is immediately to the left of the white house. Which house is second from the left?",
      ["Yellow", "Green", "White", "Blue"],
      "Red is first and blue third. Green and white must be next to each other, so they take fourth and fifth. That leaves yellow second."),
    S(2, 2, "Courses of action", "Statement: \"Cases of online fraud have risen sharply in the city.\" Courses of action: I. The police should run awareness drives on cyber fraud. II. All online banking in the city should be banned. Which course of action follows?",
      ["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"],
      "Awareness drives tackle the problem directly, so I follows. Banning all online banking is extreme and would harm everyone, so II does not."),
    S(2, 1, "Judgment", "During a festival procession, a lost child comes up to a constable on duty. What is the best first step?",
      ["Keep him safe and announce it", "Tell him to search on his own", "Take him to a hospital at once", "Ask him to wait by the road"],
      "The child's safety comes first, and an announcement is the quickest way to reach the parents in a crowd. Sending him off alone or leaving him by the road puts him at risk."),
    S(2, 3, "Symbol substitution", "If + means ÷, - means ×, × means + and ÷ means -, what is the value of 36 + 4 - 3 × 8 ÷ 5?",
      ["30", "28", "32", "25"],
      "Replace the signs: 36 ÷ 4 × 3 + 8 - 5. Then 36 ÷ 4 = 9, 9 × 3 = 27, and 27 + 8 - 5 = 30."),
    S(2, 2, "Cubes", "A cube painted blue on all its faces is cut into 64 equal smaller cubes. How many of the small cubes have no face painted?",
      ["8", "24", "16", "27"],
      "The unpainted cubes form the inner block, 4 - 2 = 2 cubes along each edge: 2 × 2 × 2 = 8. 24 is the number with exactly two faces painted."),
    S(2, 2, "Turns", "Facing south, Divya turns 135° anticlockwise and then 90° clockwise. Which direction does she face now?",
      ["South-east", "North-east", "North-west", "South-west"],
      "135° anticlockwise from south takes her through east to north-east. 90° clockwise from north-east is south-east."),
    S(2, 2, "Sets", "Of 80 recruits, 48 can swim, 36 can drive and 14 can do neither. How many can do both?",
      ["18", "14", "22", "12"],
      "80 - 14 = 66 recruits can do at least one. 48 + 36 = 84 counts those who can do both twice, so 84 - 66 = 18 can do both."),
    S(2, 1, "Decision making", "To apply for a post, a candidate must hold a degree and be between 21 and 25 years old. Sita is 24 and holds a diploma but no degree. What is the decision?",
      ["Not eligible", "Eligible", "Eligible after age relaxation", "Data inadequate"],
      "Sita meets the age rule but not the degree rule, and both are required, so she is not eligible. The data given is enough to decide."),

    # ---------- Drill only ----------
    S(0, 2, "Blood relations", "X is Y's brother. Z is Y's father. W is Z's mother. How is X related to W?",
      ["Grandson", "Son", "Nephew", "Brother"],
      "Z is the father of both X and Y, and W is Z's mother, so W is X's grandmother. X, a boy, is her grandson."),
    S(0, 1, "Directions", "Town Y is 12 km north of town X, and town Z is 5 km east of Y. How far is Z from X in a straight line?",
      ["13 km", "17 km", "7 km", "15 km"],
      "The towns form a right angle at Y, so XZ = √(12² + 5²) = √169 = 13 km. 17 km is the distance by road through Y."),
    S(0, 2, "Ordering", "Raju is heavier than Gopi but lighter than Vasu. Vasu is lighter than Sai. Kalyan is the lightest of the five. Who is the heaviest?",
      ["Sai", "Vasu", "Raju", "Gopi"],
      "From heaviest: Sai, Vasu, Raju, Gopi, Kalyan. So Sai is the heaviest."),
    S(0, 2, "Syllogism", "Statements: Some officers are athletes. All athletes are disciplined. Conclusions: I. Some officers are disciplined. II. All disciplined people are athletes. Which conclusion follows?",
      ["Only I follows", "Only II follows", "Both I and II follow", "Neither I nor II follows"],
      "The officers who are athletes must be disciplined, so I follows. \"All athletes are disciplined\" cannot be reversed into \"all disciplined people are athletes\", so II does not."),
]
